INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'Citizenship', 'Unit 1', 'Molarum Grade 10 — Citizenship Unit 1: Democracy and Democratization', 'Source-grounded Molarum Grade 10 Citizenship questions for Unit 1: Democracy and Democratization.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('55d15750-25ce-40b6-86e6-f2ca80ac4930'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'According to the textbook, from which two Greek words is the term ''democracy'' derived?', 'From the Greek words ''Demo'' and ''Kratos'' meaning people and rule', 'The excerpt states the word democracy was derived from the Greek words ''Demo'' and ''Kratos'', meaning people and rule respectively.', 0),('7494873b-3ddc-4a62-8024-e1d7f199a80c'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which dictionary-style definition of democracy is given in the excerpt?', 'A state of government in which people hold ruling power directly or indirectly through elected representatives', 'The textbook defines democracy as a state of government in which people hold ruling power either directly or indirectly through elected representatives.', 1),('a105324a-e809-4965-8842-2cfa1ae58861'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which set of values does the textbook list as central to democracy?', 'Liberty (freedom), Justice, and Equality', 'The excerpt states three core values central to democracy are liberty/freedom, justice and equality.', 2),('df768498-2b6e-4443-8a3f-7c6bca25d0ce'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which of the following best describes ''democratization'' as given in the book?', 'A complex, long-term, dynamic and open-ended process toward a more democratic political regime', 'The textbook describes democratization as a complex, long-term, dynamic and open-ended process that moves a political system toward democracy.', 3),('875b5f28-1b05-462a-825d-014e85872228'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which of the following is explicitly named as an actor in the democratization process in the excerpt?', 'Political parties', 'The excerpt names political parties as vectors of democracy and actors in the democratization process.', 4),('b8953843-d1c5-4004-89f4-80d0df4c851b'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which of the following is NOT presented in the text as an actor in the democratization process?', 'Weather systems', 'The excerpt lists political parties, civil societies and interest groups as actors, but does not present weather systems as actors in democratization.', 5),('58ceedaa-2016-4d40-83ed-56055aff5012'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'According to the book, what primary role do political parties play in democracy?', 'They are instruments through which power is attained by means of free, fair and transparent elections', 'The textbook states political parties are instruments through which power is attained by means of free, fair and transparent elections and are vectors of democracy.', 6),('de1ff582-302b-4517-8716-063fbdb1e66d'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'How does the textbook distinguish civil societies from political parties?', 'They differ in final goal but both contribute to consciousness raising and protection of rights', 'The excerpt explains that civil societies differ from political parties in their final goal but both contribute to consciousness-raising and defense of rights and freedoms.', 7),('30edd166-638f-4abb-8818-8ce9cc9ac76d'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which role of interest groups is described in the excerpt?', 'They act as transmission belts between people and government', 'The textbook states interest groups are regarded as essential transmission belts between people and government, helping citizens communicate policy wants to leaders.', 8),('33a61744-31b7-4fcc-8759-38d0bc7372b7'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'What condition does the excerpt say the media must satisfy to perform its democratic functions?', 'Be free and independent with sufficient material and human resources', 'The excerpt explains media must be free and independent and have sufficient material and human resources to perform political training and build democratic culture.', 9),('a32bdb28-69b8-43a8-87d8-8fb7d950375f'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which of the following is listed as a function of the Independent National Electoral Commission in the text?', 'Registers voters', 'The INEC functions listed in the excerpt include registering voters among other electoral responsibilities.', 10),('bfe36918-f29c-4824-8c1c-546854c4c1f4'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which of the following is one of the INEC''s specific duties as given in the textbook?', 'Provides security at the polling stations', 'The textbook lists ''provides security at the polling stations'' among the INEC''s functions.', 11),('c19aee6e-bff6-4424-8285-415b33f059ac'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which is one of the functions of political parties according to the excerpt?', 'Serve as a forum for national unity and mutual understanding', 'The excerpt lists serving as a forum for national unity and mutual understanding as a function of political parties.', 12),('6ab0080c-81ef-42da-8878-a68539f8471c'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which of the following is listed as a function of a pressure group in the book?', 'Acts as a watchdog over public policies', 'The excerpt states pressure groups act as watchdogs over public policies among other functions.', 13),('3e436b1b-ba5d-46ef-8d0d-803bee50fd26'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which of the following is NOT described in the excerpt as a component of ''liberty'' in democracy?', 'Procedural justice', 'The textbook lists personal, political and economic freedoms under liberty; procedural justice is described under the value of justice, not liberty.', 14),('334c0d7c-cadb-4c41-86b5-c997ee00b2eb'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which of these is given as a general sense of ''justice'' in the excerpt?', 'Distributive justice', 'The excerpt describes distributive justice (among others) as a general sense of the value of justice.', 15),('bd39d45e-4ca7-4834-8c90-0538a65d7a36'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'What does ''political equality'' imply in the book''s discussion of equality?', 'All adults have equal political rights (one person, one vote)', 'The excerpt states political equality implies all people who attain adulthood have equal political rights, summarized as one man-one vote-one value.', 16),('f04fa500-1c71-4eb5-8bd5-f03d41700053'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which describes the economic aspect of democracy as given in the text?', 'Equitable and just distribution of wealth and resources and recognition of rights to work and fair wages', 'The excerpt explains the economic aspect means equitable distribution of wealth, right to work, fair wages, and enjoyment of life.', 17),('c3a53e01-73eb-48eb-8c41-bc4eb7a2456d'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'Which phrase from the excerpt is used to describe democratization?', 'Complex, long-term, dynamic and open-ended process', 'The textbook explicitly describes democratization using the phrase ''complex, long-term, dynamic, and open-ended process''.', 18),('857cdc90-df04-4676-88d7-e2224f0efd9d'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'multiple_choice', 'How many lessons are listed under Unit 1 in the textbook?', 'Six', 'The excerpt lists six lessons for the unit: the concept of democracy and democratization; actors; institutionalizing democracy; role for social transformation; democratic values; and aspects of democracy.', 19),('9a0141a0-dd9e-4b96-830c-f41f1a60bc4f'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'true_false', 'The word democracy was derived from two Greek words: demos and kratos, which means common people and rule respectively.', 'True', 'The textbook explicitly states democracy was derived from demos and kratos meaning people and rule.', 20),('deadc2e6-9b04-4ef5-837a-fa67e0dbcbc3'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'true_false', 'A democratic system is the one in which citizens freely make political decisions by majority rule.', 'True', 'The unit review includes the statement that a democratic system is where citizens freely make political decisions by majority rule.', 21),('7394367f-94b7-4f81-8031-f6fc5d475fe1'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'true_false', 'Political parties are organized groups of individuals who share different political ideologies, beliefs and interests.', 'False', 'The excerpt defines political parties as organized groups who share the same political ideologies, beliefs and interests, so the statement claiming ''different'' is incorrect.', 22),('ede66253-225c-4e2a-8b4b-ea19833ae585'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'true_false', 'Like political parties, interest groups are valuable vectors of democracy.', 'True', 'The excerpt states that, like political parties, non-governmental associations and organizations (interest groups) are valuable vectors of democracy.', 23),('7f479b17-d59d-4a9d-82d3-3db5c27dc57f'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'In your own words based only on the excerpt, define ''democracy''.', 'A state of government in which people hold the ruling power either directly or indirectly through their elected representatives, implying rule by the people.', 'The excerpt defines democracy as rule by the people, where people hold ruling power directly or through elected representatives.', 24),('639f2109-3609-4c12-8c4c-95fa6d91ec11'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'Explain the meaning of ''democratization'' according to the textbook.', 'Democratization is a complex, long-term, dynamic and open-ended political process of transition toward a more rule-based, consensual and participatory democratic political regime.', 'The excerpt explains democratization as the transition to a more democratic political regime and describes it as complex, long-term, dynamic and open-ended.', 25),('0402d8c5-bdbc-4db8-8440-6692437fe4bc'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'Define a political party based on the excerpt.', 'An organized group of individuals who share the same political ideologies, beliefs and interests and who seek to win elections and control state power and machinery of government.', 'The textbook defines political parties as organized groups sharing the same ideologies and seeking to win elections to control state power.', 26),('55b96d14-a85a-48ec-8508-cbaae1214de9'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'According to the textbook, what is an interest group?', 'An organization or group of people autonomous from government or political parties with the objective of influencing government and promoting members'' interests.', 'The excerpt defines interest groups as autonomous organizations aiming to influence government and promote the interests of their members.', 27),('66903692-e03e-4777-80c2-9e601dd47131'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'Define the Independent National Electoral Commission as presented in the excerpt.', 'A corporate body charged with organizing, conducting and supervising elections into electoral offices in the country.', 'The excerpt defines the Independent National Electoral Commission as a corporate body responsible for organizing, conducting and supervising elections.', 28),('a6be1d56-a881-4c87-8702-54f69a8d190b'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'What is ''civic engagement'' according to the text?', 'The many ways people participate in civic, community, and political life—ranging from becoming informed, participating in public dialogue, volunteering, voting, community organizing to political advocacy, with commitment to improve one''s community.', 'The excerpt defines civic engagement as participation in civic and political life including being informed, dialogue, volunteering, voting and advocacy to improve community life.', 29),('5834daaf-b759-4902-8573-bd82158c99bc'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'List the three core values of democracy named in the excerpt.', 'Liberty (freedom), Justice, and Equality.', 'The excerpt names liberty/freedom, justice and equality as the three core values central to democracy.', 30),('6466b2f3-b9f0-4055-89ba-e3c3bb19a277'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'Using the glossary in the excerpt, how can ''civic societies'' be understood?', 'As the ''third sector'' of society, distinct from government and business, including the family and the private sphere.', 'The glossary defines civic societies as the ''third sector'' distinct from government and business, including family and the private sphere.', 31),('531c0583-8cf1-466d-8068-9efee026bca9'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'How many functions of the Independent National Electoral Commission are listed in Table 1.1 of the excerpt?', '9', 'The excerpt lists nine functions of the Independent National Electoral Commission, numbered 1 through 9.', 32),('ee763fd3-44b4-4d5b-8990-57fb8f20a021'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'How many functions of political parties are enumerated in the excerpt?', '9', 'The textbook lists nine functions performed by political parties, numbered in the excerpt.', 33),('3a794527-1e3f-4075-846c-2b4fc4697e64'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'How many functions of pressure groups are listed in the excerpt?', '8', 'The excerpt presents eight functions of pressure groups, numbered 1 through 8.', 34),('343d6724-bf73-4bed-8f79-e17dafb01911'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'How many ways of social transformation are listed under lesson 1.4 (a–e)?', '5', 'Lesson 1.4 lists five manifestations of social transformation labeled a) through e).', 35),('d1d9e38d-cd7e-4cb1-8423-e1b57eca8bc5'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'How many core values of democracy are identified in the excerpt?', '3', 'The excerpt identifies three core values central to democracy: liberty, justice and equality.', 36),('1e05abce-4138-44d5-87e5-3e0532b13508'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'According to lesson 1.6, how many major aspects of democracy are described?', '3', 'Lesson 1.6 states democracy has three aspects: social, economic and political.', 37),('52bbfdc9-ff5e-4983-847a-70c4fd8f9a0a'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'How many key words are listed near the start of Unit 1?', '8', 'The excerpt lists eight key words at the start of the unit (Accountability, Democracy, Democratization, Federal government, Majority rule, Sovereignty, The rule of law, Tolerance).', 38),('e07aa497-e27d-44ec-8a3d-113f1342f5ea'::uuid, '6a8493b9-d36e-40a1-8240-a8c5aefb45aa'::uuid, 'fill_blank', 'How many lessons are contained in Unit 1 as listed in the excerpt?', '6', 'The excerpt lists six lessons under Unit 1, so the number of lessons is six.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
INSERT INTO public.choices (id, question_id, choice_text, is_correct, order_index) VALUES ('4bcd0c92-3508-43ba-8e20-48b50045aebd'::uuid, '55d15750-25ce-40b6-86e6-f2ca80ac4930'::uuid, 'From the Greek words ''Demo'' and ''Kratos'' meaning people and rule', TRUE, 0),('3c4405a1-ac6d-4dad-8730-42378ed22b95'::uuid, '55d15750-25ce-40b6-86e6-f2ca80ac4930'::uuid, 'From the Greek words ''Demos'' and ''Polis'' meaning people and city', FALSE, 1),('7a5b3b1a-65bb-45c2-85e8-e02af274f578'::uuid, '55d15750-25ce-40b6-86e6-f2ca80ac4930'::uuid, 'From the Greek words ''Kratos'' and ''Nomos'' meaning rule and law', FALSE, 2),('b5fcae43-e1cb-47c5-8198-1bc3bdf8246a'::uuid, '55d15750-25ce-40b6-86e6-f2ca80ac4930'::uuid, 'From the Greek words ''Demo'' and ''Nomos'' meaning people and law', FALSE, 3),('6a2099a4-94ae-4dab-812d-706c30327b9b'::uuid, '7494873b-3ddc-4a62-8024-e1d7f199a80c'::uuid, 'A state of government in which people hold ruling power directly or indirectly through elected representatives', TRUE, 0),('c7549552-473b-49ca-813a-a483ec166142'::uuid, '7494873b-3ddc-4a62-8024-e1d7f199a80c'::uuid, 'A system where rule is exercised exclusively by hereditary monarchs', FALSE, 1),('0a267185-6725-41a9-8e46-1e0dc434143a'::uuid, '7494873b-3ddc-4a62-8024-e1d7f199a80c'::uuid, 'A political order where a single party permanently controls the state', FALSE, 2),('f8c2cbea-8f59-4983-8c10-5d5e1f3f45bf'::uuid, '7494873b-3ddc-4a62-8024-e1d7f199a80c'::uuid, 'A society where decisions are made only by informal community elders', FALSE, 3),('5718cccd-89f1-4c39-861b-4951c0a541a2'::uuid, 'a105324a-e809-4965-8842-2cfa1ae58861'::uuid, 'Liberty (freedom), Justice, and Equality', TRUE, 0),('8aa4bc93-0bd6-4836-82b7-a452653539dc'::uuid, 'a105324a-e809-4965-8842-2cfa1ae58861'::uuid, 'Authority, Tradition, and Hierarchy', FALSE, 1),('6cc41b34-19b2-4dd9-8e25-8fc67feccf99'::uuid, 'a105324a-e809-4965-8842-2cfa1ae58861'::uuid, 'Wealth accumulation, Monopolies, and Status', FALSE, 2),('fb0c075b-4fd8-4b93-8b15-4bda335436